CREATE TABLE sellers (id uuid PRIMARY KEY, name text NOT NULL, internal_number text UNIQUE NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wb_accounts (id uuid PRIMARY KEY, seller_id uuid NOT NULL REFERENCES sellers(id), display_name text NOT NULL, external_id text, secret_ref text NOT NULL, scopes jsonb NOT NULL, mode text NOT NULL, status text NOT NULL, checkpoint jsonb, diagnostics jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (id, seller_id));
CREATE TABLE wb_assembly_tasks (id uuid PRIMARY KEY, seller_id uuid NOT NULL, wb_account_id uuid NOT NULL REFERENCES wb_accounts(id), wb_order_id bigint NOT NULL, wb_order_uid text, wb_status text NOT NULL, canonical_status text NOT NULL, payload_checksum text NOT NULL, version integer NOT NULL DEFAULT 1, wms_task_id text, wb_supply_id text, transport_box_id text, delivery_batch_id uuid, label_id uuid, manual_review_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (wb_account_id, wb_order_id));
CREATE TABLE raw_snapshots (id uuid PRIMARY KEY, wb_account_id uuid NOT NULL REFERENCES wb_accounts(id), wb_order_id bigint NOT NULL, payload jsonb NOT NULL, checksum text NOT NULL, api_method text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), retention_until timestamptz NOT NULL);
CREATE TABLE inbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE TABLE outbox (id uuid PRIMARY KEY, aggregate_id uuid NOT NULL, message_type text NOT NULL, idempotency_key text NOT NULL UNIQUE, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dead_letters (id uuid PRIMARY KEY, source_outbox_id uuid, reason text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
